    auctionSentences: [
      { sentence:"I'd rather walk to work than take the bus.", isCorrect:true, explanation:"'Would rather + bare infinitive + than + bare infinitive' is the correct structure." },
      { sentence:"She'd prefer to walking in the park after dinner.", isCorrect:false, explanation:"'Would prefer to' is followed by a bare infinitive, not a gerund: 'prefer to walk'." },
      { sentence:"He'd prefer tea to coffee this morning.", isCorrect:true, explanation:"'Prefer + noun + to + noun' is the correct comparative form." },
      { sentence:"I'd rather washing the dishes than cooking tonight.", isCorrect:false, explanation:"'Would rather' is followed by a bare infinitive, not a gerund: 'I'd rather wash... than cook'." },
      { sentence:"We'd rather you called us before coming over.", isCorrect:true, explanation:"'Would rather + subject + past simple' expresses a present preference about someone else's action." },
      { sentence:"She'd prefer to stay in rather than go to the party.", isCorrect:true, explanation:"'Prefer to do rather than do' is the correct full form." },
      { sentence:"I'd rather you don't smoke in the house.", isCorrect:false, explanation:"After 'would rather + subject', use the past simple for a present request: 'I'd rather you didn't smoke'." },
      { sentence:"He'd prefer staying home than going out.", isCorrect:false, explanation:"'Prefer' compares with 'to', not 'than': 'prefer staying home to going out'." },
      { sentence:"I'd rather not answer that question right now.", isCorrect:true, explanation:"'Would rather not + bare infinitive' is the correct negative form." },
      { sentence:"They'd rather to travel by train than fly.", isCorrect:false, explanation:"'Would rather' takes a bare infinitive — no 'to': 'they'd rather travel'." },
    ],
