    auctionSentences: [
      { sentence:"What is she like? She's very friendly and outgoing.", isCorrect:true, explanation:"'What is...like?' correctly asks about someone's personality." },
      { sentence:"What does your neighbor like? He's quiet and polite.", isCorrect:false, explanation:"'What does...like?' asks about preferences, not personality; it should be 'What is your neighbor like?'" },
      { sentence:"He is a very generous person. He always shares his lunch.", isCorrect:true, explanation:"'A generous person' correctly uses the article before adjective plus noun." },
      { sentence:"My aunt is a stubbornly woman who never changes her mind.", isCorrect:false, explanation:"'Stubborn' is the adjective needed here; 'stubbornly' is an adverb and cannot describe a noun this way." },
      { sentence:"She is honest but a little impatient.", isCorrect:true, explanation:"Two adjectives are correctly contrasted with 'but', with no article needed before them." },
      { sentence:"Our new manager is a hardworking but very demanding.", isCorrect:false, explanation:"Don't use 'a' before standalone adjectives: it should be 'is hardworking but very demanding'." },
      { sentence:"Her cousin Marco is ambitious and confident.", isCorrect:true, explanation:"Adjectives describing personality are correctly used without an article." },
      { sentence:"What is his roommate like? He's a kind and funny.", isCorrect:false, explanation:"No article is needed before adjectives joined by 'and': it should be 'He's kind and funny'." },
      { sentence:"My grandfather is patient and wise.", isCorrect:true, explanation:"Adjectives are correctly joined with 'and', with no article needed." },
      { sentence:"My classmates are very talkatively during lunch break.", isCorrect:false, explanation:"'Talkative' is the adjective needed here; 'talkatively' is an adverb and cannot follow 'be'." },
    ],
