    auctionSentences: [
      { sentence:"Social media has changed the way young people interact with one another.", isCorrect:true, explanation:"'Social media' is treated as a singular, uncountable noun in modern usage — 'has' is correct." },
      { sentence:"Wearable fitness trackers allow users to monitor their sleep patterns.", isCorrect:true, explanation:"Correct plural agreement: a plural subject ('trackers') takes the plural verb 'allow'." },
      { sentence:"Cybersecurity experts are racing to patch the vulnerability before hackers exploit it.", isCorrect:true, explanation:"Correct plural agreement: 'experts' takes 'are', not 'is'." },
      { sentence:"It is hard to imagine a classroom today without at least one digital device.", isCorrect:true, explanation:"'Hard to imagine' followed by a noun phrase is correctly formed here." },
      { sentence:"Renewable energy technologies are becoming more affordable every year.", isCorrect:true, explanation:"'Technologies' is plural, so it takes 'are becoming', not 'is becoming'." },
      { sentence:"Video conferencing tools has made remote work far more practical.", isCorrect:false, explanation:"'Tools' is plural — it needs 'have', not 'has': 'tools have made'." },
      { sentence:"Parents are increasingly concerned for the amount of time children spend online.", isCorrect:false, explanation:"The correct preposition is 'about' — 'concerned about', not 'concerned for'." },
      { sentence:"3D printing has resulted a dramatic drop in prototyping costs.", isCorrect:false, explanation:"'Result in' requires the preposition 'in': 'has resulted in a dramatic drop'." },
      { sentence:"It is hard to imagine live a single day without a smartphone nowadays.", isCorrect:false, explanation:"After 'imagine', use the -ing form: 'imagine living', not 'imagine live'." },
      { sentence:"Robotics engineers is developing machines that can perform delicate surgery.", isCorrect:false, explanation:"'Engineers' is plural — it needs 'are', not 'is': 'engineers are developing'." },
    ],
